 "content": "def transform(grid):
    """Overlay two equally sized masks separated by a solid divider.

    Cells occupied in both masks become 2; all other cells become 0.
    """
    h, w = len(grid), len(grid[0])
    divider = None
    # Find a solid, non-background row or column dividing the two panels.
    for r, row in enumerate(grid):
        if row and row[0] != 0 and all(v == row[0] for v in row):
            divider = ("row", r)
            break
    if divider is None:
        for c in range(w):
            v = grid[0][c]
            if v != 0 and all(row[c] == v for row in grid):
                divider = ("col", c)
                break
    if divider is None:
        raise ValueError("No solid divider found")

    axis, pos = divider
    if axis == "row":
        top, bottom = grid[:pos], grid[pos + 1:]
        if len(top) != len(bottom) or not top:
            raise ValueError("Panels are not equally sized")
        return [[2 if a != 0 and b != 0 else 0 for a, b in zip(ra, rb)]
                for ra, rb in zip(top, bottom)]

    left = [row[:pos] for row in grid]
    right = [row[pos + 1:] for row in grid]
    if len(left[0]) != len(right[0]) or not left[0]:
        raise ValueError("Panels are not equally sized")
    return [[2 if a != 0 and b != 0 else 0 for a, b in zip(ra, rb)]
            for ra, rb in zip(left, right)]
